DROP TABLE IF EXISTS nbatch_work_run_node_log;

CREATE TABLE nbatch_work_run_node_log (
  node_log_id varchar(32) NOT NULL,
  work_id varchar(32) NOT NULL,
  node_id varchar(32) NOT NULL,
  turn_date date DEFAULT NULL,
  handle_code integer NOT NULL,
  handle_msg text,
  executor_address varchar(32) DEFAULT NULL,
  create_time timestamp DEFAULT NULL,
  execute_start_time timestamp DEFAULT NULL,
  execute_end_time timestamp DEFAULT NULL,
  last_active_time timestamp DEFAULT NULL,
  call_back_time timestamp DEFAULT NULL,
  PRIMARY KEY (node_log_id)
);
COMMENT ON TABLE nbatch_work_run_node_log IS '作业运行节点日志表';
COMMENT ON COLUMN nbatch_work_run_node_log.node_log_id IS '节点日志id';
COMMENT ON COLUMN nbatch_work_run_node_log.work_id IS '作业id';
COMMENT ON COLUMN nbatch_work_run_node_log.node_id IS '作业节点id';
COMMENT ON COLUMN nbatch_work_run_node_log.turn_date IS '翻牌日期';
COMMENT ON COLUMN nbatch_work_run_node_log.handle_code IS '执行状态';
COMMENT ON COLUMN nbatch_work_run_node_log.handle_msg IS '执行信息';
COMMENT ON COLUMN nbatch_work_run_node_log.executor_address IS '执行器地址';
COMMENT ON COLUMN nbatch_work_run_node_log.create_time IS '执行-时间';
COMMENT ON COLUMN nbatch_work_run_node_log.execute_start_time IS '实际开始执行时间';
COMMENT ON COLUMN nbatch_work_run_node_log.execute_end_time IS '实际结束执行时间';
COMMENT ON COLUMN nbatch_work_run_node_log.last_active_time IS '最后活跃时间';
COMMENT ON COLUMN nbatch_work_run_node_log.call_back_time IS '执行-时间';
CREATE INDEX idx_work_node_turn_callback_create ON nbatch_work_run_node_log (work_id,node_id,turn_date,call_back_time,create_time);


DROP TABLE IF EXISTS nbatch_work_run_node_log_detail;

CREATE TABLE nbatch_work_run_node_log_detail (
  detail_log_id varchar(32) NOT NULL,
  node_log_id varchar(32) NOT NULL,
  work_id varchar(32) NOT NULL,
  node_id varchar(32) NOT NULL,
  turn_date date DEFAULT NULL,
  handle_msg text,
  create_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  execute_time timestamp DEFAULT NULL,
  call_back_time timestamp DEFAULT NULL,
  PRIMARY KEY (detail_log_id)
);
COMMENT ON TABLE nbatch_work_run_node_log_detail IS '作业运行节点日志表';
COMMENT ON COLUMN nbatch_work_run_node_log_detail.detail_log_id IS '节点日志id';
COMMENT ON COLUMN nbatch_work_run_node_log_detail.node_log_id IS 'single execution log id';
COMMENT ON COLUMN nbatch_work_run_node_log_detail.work_id IS '作业id';
COMMENT ON COLUMN nbatch_work_run_node_log_detail.node_id IS '作业节点id';
COMMENT ON COLUMN nbatch_work_run_node_log_detail.turn_date IS '翻牌日期';
COMMENT ON COLUMN nbatch_work_run_node_log_detail.handle_msg IS '执行信息';
COMMENT ON COLUMN nbatch_work_run_node_log_detail.create_time IS '创建时间';
COMMENT ON COLUMN nbatch_work_run_node_log_detail.execute_time IS '执行-时间';
COMMENT ON COLUMN nbatch_work_run_node_log_detail.call_back_time IS '执行-时间';
CREATE INDEX idx_node_log_id ON nbatch_work_run_node_log_detail (node_log_id);

