-- Preserve the MySQL ON UPDATE CURRENT_TIMESTAMP behavior of nbatch_work.update_time.
CREATE OR REPLACE FUNCTION nbatch_work_set_update_time()
RETURNS TRIGGER
AS $$
BEGIN
    NEW.update_time := CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_nbatch_work_update_time
BEFORE UPDATE ON nbatch_work
FOR EACH ROW
EXECUTE PROCEDURE nbatch_work_set_update_time();
